import { Suspense, use, useMemo } from 'react';

export type Profile = { id: number; name: string };

export async function fetchProfile(id: number): Promise<Profile> {
  const r = await fetch(`/api/profile/${id}`);
  return r.json() as Promise<Profile>;
}

export function ProfileView({ profilePromise }: { profilePromise: Promise<Profile> }) {
  const profile = use(profilePromise);
  return <p>{profile.name}</p>;
}

export function Page({ id }: { id: number }) {
  const promise = useMemo(() => fetchProfile(id), [id]);
  return (
    <Suspense fallback={<p>loading</p>}>
      <ProfileView profilePromise={promise} />
    </Suspense>
  );
}
